<template>
  <section class="personal-knowledge">
    <header class="page-header"><div><p class="eyebrow">PERSONAL KNOWLEDGE</p><h1>我的知识库</h1><p class="muted">只属于当前操作人员的排障经验，可从故障候选审核后沉淀。</p></div><div class="header-actions"><button class="primary" type="button" @click="createLibrary">新建知识库</button><button v-if="selected" type="button" @click="reindex">重建索引</button></div></header>
    <nav class="zone-tabs" aria-label="Knowledge zones"><RouterLink class="zone-tab" to="/knowledge">系统知识库</RouterLink><RouterLink class="zone-tab active" to="/knowledge/personal">我的知识库</RouterLink><RouterLink class="zone-tab" to="/knowledge/quiz">题库</RouterLink><RouterLink class="zone-tab" to="/knowledge/review">待审核候选</RouterLink></nav>
    <p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="notice" class="notice" role="status">{{ notice }}</p>
    <div class="layout">
      <aside class="libraries"><div class="panel-heading"><h2>知识库</h2><span>{{ libraries.length }}</span></div><button v-for="library in libraries" :key="library.id" :class="{ active: selected?.id === library.id }" type="button" @click="selectLibrary(library)"><span>{{ library.name }}</span><small>{{ library.description || '个人资料' }}</small><small class="library-status">{{ library.status || library.storageStatus || 'ACTIVE' }}</small></button><p v-if="!libraries.length" class="muted">还没有个人知识库。</p></aside>
      <main class="entries"><div class="section-head"><div><h2>{{ selected?.name || '选择知识库' }}</h2><small v-if="selected" class="panel-meta">{{ selected.status || 'ACTIVE' }} · {{ selected.storageSlug || 'LOCAL' }}</small></div><button v-if="selected" type="button" @click="createEntry">新建条目</button></div><label v-if="selected" class="search">搜索<input v-model="query" type="search" @keyup.enter="loadEntries" /></label><article v-for="entry in entries" :key="entry.id" class="entry" :class="{ selected: selectedEntry?.id === entry.id }" tabindex="0" @click="selectEntry(entry)" @keydown.enter="selectEntry(entry)"><div><h3>{{ entry.title }}</h3><p>{{ entry.summary }}</p><small>{{ entry.sourceType }} · {{ entry.verificationStatus }} · v{{ entry.version }}</small></div><button type="button" @click.stop="archive(entry)">归档</button></article><p v-if="selected && !entries.length" class="empty">暂无个人知识条目。</p></main>
      <aside class="detail"><template v-if="selectedEntry"><div class="detail-heading"><h2>Markdown 编辑器</h2><span>保存后写入本地文件</span></div><input v-model="draft.title" class="editor-input" aria-label="条目标题" /><textarea v-model="draft.contentMarkdown" class="editor" aria-label="Markdown 内容" rows="18"></textarea><button type="button" class="primary" @click="saveEntry">保存条目</button></template><template v-else><h2>工作区状态</h2><p v-if="selected">{{ selected.storageStatus || 'ACTIVE' }} · {{ selected.storageSlug || '本地目录已配置' }}</p><p v-else class="muted">选择一个个人知识库查看本地目录和索引状态。</p><p class="muted">个人内容只对当前用户可见，未确认候选不会进入正式搜索。</p></template></aside>
    </div>
  </section>
</template>

<script setup>
import { onMounted, ref } from 'vue'
import { RouterLink } from 'vue-router'
import { createKnowledgeEntry, createKnowledgeLibrary, listKnowledgeLibraries, reindexKnowledgeLibrary, archiveKnowledgeEntry, getKnowledgeEntries, updateKnowledgeEntry } from '../../api/personalKnowledge.ts'
const libraries = ref([]), selected = ref(null), entries = ref([]), selectedEntry = ref(null), draft = ref({ title: '', contentMarkdown: '' }), query = ref(''), error = ref(''), notice = ref('')
const unwrap = value => value?.data ?? value
async function createLibrary() { const name = window.prompt('知识库名称')?.trim(); if (!name) return; try { const result = unwrap(await createKnowledgeLibrary({ name, description: '个人排障经验' })); libraries.value.push(result); await selectLibrary(result); notice.value = '知识库已创建'; error.value = '' } catch (cause) { error.value = cause.message || '创建失败' } }
async function createEntry() { if (!selected.value) return; const title = window.prompt('条目标题')?.trim(); if (!title) return; const contentMarkdown = window.prompt('Markdown 内容')?.trim(); if (!contentMarkdown) return; try { await createKnowledgeEntry(selected.value.id, { title, summary: '手动创建的个人经验', contentMarkdown, sourceType: 'MANUAL' }); await loadEntries(); notice.value = '知识条目已创建'; error.value = '' } catch (cause) { error.value = cause.message || '创建失败' } }
async function selectLibrary(library) { selected.value = library; selectedEntry.value = null; await loadEntries() }
function selectEntry(entry) { selectedEntry.value = entry; draft.value = { title: entry.title, contentMarkdown: entry.contentMarkdown || entry.summary || '' } }
async function loadEntries() { if (!selected.value) return; try { const result = unwrap(await getKnowledgeEntries(selected.value.id, { query: query.value })); entries.value = result.items || [] } catch (cause) { error.value = cause.message || '读取失败' } }
async function archive(entry) { try { await archiveKnowledgeEntry(entry.id); await loadEntries(); notice.value = '条目已归档' } catch (cause) { error.value = cause.message || '归档失败' } }
async function saveEntry() { if (!selectedEntry.value) return; try { const result = unwrap(await updateKnowledgeEntry(selectedEntry.value.id, { title: draft.value.title, summary: selectedEntry.value.summary, contentMarkdown: draft.value.contentMarkdown })); selectedEntry.value = result; await loadEntries(); notice.value = '条目已保存'; error.value = '' } catch (cause) { error.value = cause.message || '保存失败' } }
async function reindex() { if (!selected.value) return; try { const result = unwrap(await reindexKnowledgeLibrary(selected.value.id)); notice.value = `索引完成：${result.ready || 0} 条`; error.value = '' } catch (cause) { error.value = cause.message || '索引失败' } }
onMounted(async () => { try { const result = unwrap(await listKnowledgeLibraries()); libraries.value = Array.isArray(result) ? result : (result?.items || []) } catch (cause) { const raw = localStorage.getItem('smartops_personal_knowledge_libraries'); libraries.value = raw ? JSON.parse(raw) : []; error.value = cause.message || '读取个人知识库失败' } })
</script>

<style scoped>
