ted);font-size:10px}.library-status,.panel-meta{color:var(--smart-primary-strong)!important}.search{display:block;margin:10px 0;color:var(--smart-muted);font-size:11px}.search input,.editor-input{display:block;width:100%;box-sizing:border-box;margin-top:6px;padding:10px;background:var(--smart-bg);border:1px solid var(--smart-border);color:var(--smart-text);min-height:42px}.entry{display:flex;justify-content:space-between;gap:12px;padding:14px 0;border-top:1px solid var(--smart-border);cursor:pointer;min-width:0}.entry>div{min-width:0}.entry.selected,.entry:focus-visible{background:color-mix(in srgb,var(--smart-primary-strong) 8%,transparent);outline:2px solid var(--smart-primary-strong);outline-offset:-2px}.entry h3{margin:0;font-size:14px;overflow-wrap:anywhere}.entry p{margin:7px 0;color:var(--smart-muted);font-size:12px;overflow-wrap:anywhere}.entry small{color:var(--smart-muted);font:10px var(--font-mono);overflow-wrap:anywhere}.detail{min-height:180px}.detail-heading{display:flex;justify-content:space-between;gap:10px;align-items:baseline}.detail-heading span{color:var(--smart-muted);font-size:10px}.detail p{color:var(--smart-muted);font-size:12px;line-height:1.7;overflow-wrap:anywhere}.editor{width:100%;box-sizing:border-box;margin:10px 0;resize:vertical;background:var(--smart-bg);border:1px solid var(--smart-border);color:var(--smart-text);font:12px/1.6 var(--font-mono);padding:10px;min-height:280px}.error{color:var(--smart-danger);font-size:12px}.notice{color:var(--smart-primary-strong);font-size:12px}.empty{padding:35px;text-align:center;color:var(--smart-muted);font-size:12px}@media(max-width:1100px){.layout{grid-template-columns:220px minmax(0,1fr)}.detail{grid-column:1/-1}}@media(max-width:700px){.personal-knowledge{padding:12px}.page-header{flex-direction:column;gap:14px}.header-actions{width:100%}.header-actions button{flex:1}.layout{grid-template-columns:1fr;gap:12px}.libraries,.entries,.detail{padding:14px}.section-head{gap:10px}.entry{align-items:flex-start}.entry>button{flex:0 0 auto;padding-inline:10px}.zone-tabs{margin-top:16px}.zone-tab{flex:1;justify-content:center;padding-inline:8px}}
@media(max-width:900px){.layout{grid-template-columns:1fr}.detail{grid-column:auto}}
</style>
